// book1.js -- BOOK ONE, SEASON 0 (2026-10-21, the designer: "we need three kinds of quests ... game-centered, story and
// side quests ... begin with the story quest"; the plan: design/story/BOOK_ONE_PLAN.md). The quests of a Season 0 farm:
//
//   STORY       chain 'story', bk01 to bk45: Book One's chapters, one quest each (here: Parts One to Three, bk01 to bk17;
//               Parts Four to Eight come in weekly updates). Each region's door opens with its chapter.
//   GAME        chain 'game', g_*: a townsperson teaches each skill and each system, from chapter 6.
//   SIDE        chain 'sidequest', sd_*: the townsfolk's own small troubles. Most want goods the shops will not take.
//
// Every quest here is marked s0: it starts only for a farm of Season 0 (quests.js retired), and the playtest's quests
// never start for one. The quest format is quests.js's own (its header); `level` is a step of Book One's: a skill at
// level n or more (the parts ask for levels, so the season lasts as long as the designer wants).

const T = (npc, text, lines, more = {}) => ({ kind: 'talk', npc, text, lines, ...more });
const C = (clue, place, text, lines, more = {}) => ({ kind: 'clue', clue, place, text, lines, ...more });
const V = (map, text, where = null) => ({ kind: 'visit', map, text, ...(where ? { where } : {}) });
const D = (on, text, more = {}) => ({ kind: 'do', on, n: 1, text, ...more });
const M = (npc, text) => ({ kind: 'meet', npc, text });
const L = (skill, n, text, where) => ({ kind: 'level', skill, n, text, where });
// THE STORY ASKS FOR NO LEVEL (2026-10-22, the designer: "The story should not directly involve itself with the player's
// level ... player can have their skills fully maxed and can still complete the story"): the chapters' level steps are
// kept in their places -- a farmer part way through a chapter keeps their step -- but each is met at once (level 1) and
// passed as it comes up (quests.js enter, onEvent).
const PASSED = (skill) => ({ kind: 'level', skill, n: 1, text: 'On with the story', where: 'Nothing to do here. On you go.' });
const G = (npc, text, items, more = {}) => ({ kind: 'deliver', npc, text, items, ...more });

